using System.ComponentModel.DataAnnotations;
namespace RaceDay.Mvc.Models;
public class LoginVm { [Required,EmailAddress] public string Email{get;set;}=""; [Required] public string Password{get;set;}=""; }
public class RegisterVm { [Required,StringLength(100)] public string FullName{get;set;}=""; [Required,EmailAddress] public string Email{get;set;}=""; [Required,StringLength(100,MinimumLength=8)] public string Password{get;set;}=""; [Required] public string Role{get;set;}="Participant"; public string? PhoneNumber{get;set;} public string? OrganiserCode{get;set;} }
public class EventVm { public int EventId{get;set;} [Required,StringLength(150)] public string Name{get;set;}=""; public string? Description{get;set;} [Required] public string EventType{get;set;}="Run"; [Required] public DateTime EventDate{get;set;}=DateTime.Today.AddDays(14); [Required] public string Location{get;set;}=""; [Required] public string Province{get;set;}="Gauteng"; public string Status{get;set;}="Upcoming"; }
public class CategoryVm { [Required] public string Name{get;set;}=""; [Range(.01,9999.99)] public decimal DistanceKm{get;set;}=5; [Range(0,999999.99)] public decimal EntryFee{get;set;} public int MaxParticipants{get;set;}=100; public int MinAge{get;set;} }
public class EnrolVm { public int CategoryId{get;set;} }
public class ResultVm { public int EventId{get;set;} public int EnrolmentId{get;set;} public TimeSpan? FinishTime{get;set;} public int? Position{get;set;} public string Status{get;set;}="Finished"; }
public class ProfileVm { [Required] public string FullName{get;set;}=""; public string? PhoneNumber{get;set;} public string? Email{get;set;} }
public class ApiUser { public int UserId{get;set;} public string FullName{get;set;}=""; public string Email{get;set;}=""; public string Role{get;set;}=""; public string? PhoneNumber{get;set;} }
public class ApiEvent { public int EventId{get;set;} public int OrganiserId{get;set;} public string Name{get;set;}=""; public string? Description{get;set;} public string EventType{get;set;}=""; public DateTime EventDate{get;set;} public string Location{get;set;}=""; public string Province{get;set;}=""; public string Status{get;set;}="Upcoming"; public List<ApiCategory> Categories{get;set;}=[]; }
public class ApiCategory { public int CategoryId{get;set;} public int EventId{get;set;} public string Name{get;set;}=""; public decimal DistanceKm{get;set;} public decimal EntryFee{get;set;} public int MaxParticipants{get;set;} public int MinAge{get;set;} }
public class ApiEnrolment { public int EnrolmentId{get;set;} public int CategoryId{get;set;} public int EventId{get;set;} public string CategoryName{get;set;}=""; public string EventName{get;set;}=""; public DateTime EventDate{get;set;} public string Status{get;set;}=""; public string? ParticipantName{get;set;} public string? ParticipantEmail{get;set;} public string? RaceNumber{get;set;} }
public class ApiResult { public int ResultId{get;set;} public int EnrolmentId{get;set;} public string EventName{get;set;}=""; public string CategoryName{get;set;}=""; public string ParticipantName{get;set;}=""; public string Status{get;set;}=""; public TimeSpan? FinishTime{get;set;} public int? Position{get;set;} }
